-- | The class of a codepoint above ASCII, or @0@ if it is not a letter.
letterClass :: Char -> Int
letterClass c = search 0 (U.length ranges `div` 3 - 1)
  where
    code = fromEnum c
    search low high
      | low > high = 0
      | code < U.unsafeIndex ranges (mid * 3) = search low (mid - 1)
      | code > U.unsafeIndex ranges (mid * 3 + 1) = search (mid + 1) high
      | otherwise = U.unsafeIndex ranges (mid * 3 + 2)
      where
        mid = low + (high - low) `div` 2

